CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT CHECK(c0 IS NULL OR length(c0) < 40), c1 INTEGER UNIQUE, c2 TEXT COLLATE NOCASE, c3);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES(NULL, x'd974c4cca8', x'e8', x'569fd59682ec');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL UNIQUE, c1 TEXT UNIQUE, c2 INTEGER COLLATE NOCASE, c3 INTEGER, ref INTEGER REFERENCES t0(id)) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(49.242, 'xi', -330, -324, 7);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-43.662, 'chi', 474, -304, 4);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(-40.219, 'kappa', 216, 0.1, 2);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 BLOB, c1 NUMERIC COLLATE NOCASE, c2 BLOB DEFAULT 'd');
SELECT length(''), upper(''), lower(''), substr('', 4, 4), instr('', 'gamma'), replace('', 'a', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%', '' GLOB 'a*', char(77, 689), '' || 'gamma', '' < 'gamma', '' = 'gamma' COLLATE NOCASE;
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', -1, 1), instr('gamma', 'omega'), replace('gamma', 'a', ''), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE '%', 'gamma' GLOB '?', char(67, 765), 'gamma' || 'omega', 'gamma' < 'omega', 'gamma' = 'omega' COLLATE NOCASE;
SELECT length('über'), upper('über'), lower('über'), substr('über', 3, 5), instr('über', 'alpha'), replace('über', 'a', ''), trim('über'), ltrim('über', 'ab'), hex('über'), quote('über'), unicode('über'), 'über' LIKE '_', 'über' GLOB '*', char(68, 597), 'über' || 'alpha', 'über' < 'alpha', 'über' = 'alpha' COLLATE NOCASE;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', -1, 5), instr('-7', 'Ελλάδα'), replace('-7', '', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '%é%', '-7' GLOB '*', char(90, 560), '-7' || 'Ελλάδα', '-7' < 'Ελλάδα', '-7' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', -2, 1), instr('sigma', 'pi'), replace('sigma', 'é', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%a_', 'sigma' GLOB '*', char(90, 943), 'sigma' || 'pi', 'sigma' < 'pi', 'sigma' = 'pi' COLLATE NOCASE;
SELECT length('xi'), upper('xi'), lower('xi'), substr('xi', 4, 5), instr('xi', 'psi'), replace('xi', 'e', ''), trim('xi'), ltrim('xi', 'ab'), hex('xi'), quote('xi'), unicode('xi'), 'xi' LIKE '%', 'xi' GLOB '?', char(68, 641), 'xi' || 'psi', 'xi' < 'psi', 'xi' = 'psi' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', 4, 2), instr('café', '1e3'), replace('café', '', 'XY'), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE 'a%', 'café' GLOB '*[a-m]*', char(79, 916), 'café' || '1e3', 'café' < '1e3', 'café' = '1e3' COLLATE NOCASE;
SELECT count(*), count(c0), sum(c0), total(c0), avg(c0), min(c0), max(c0), count(DISTINCT c0) FROM t2;
SELECT c0, count(*), group_concat(id) FROM (SELECT * FROM t2 ORDER BY id) GROUP BY c0 ORDER BY c0;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 1, 5), instr('pi', 'Ελλάδα'), replace('pi', '', 'XY'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '_', 'pi' GLOB '*', char(69, 887), 'pi' || 'Ελλάδα', 'pi' < 'Ελλάδα', 'pi' = 'Ελλάδα' COLLATE NOCASE;
